import re

def parse_size(text):
    pattern = r'^\d+(?:KB|MB|GB|B)$'
    match = re.match(pattern, text)
    if match:
        size_str, unit = match.groups()
        size_str = size_str.strip()
        if unit == 'B':
            return int(size_str)
        elif unit == 'KB':
            return int(size_str) * 1024
        elif unit == 'MB':
            return int(size_str) * 1024**2
        elif unit == 'GB':
            return int(size_str) * 1024**3
    else:
        raise ValueError

