def compare_versions(a, b):
    pattern = r'^([0-9]+)\.([0-9]+)\.([0-9]+)$'
    if not re.match(pattern, a) or not re.match(pattern, b):
        raise ValueError('Malformed version string')

    parts_a = list(map(int, a.split('.')))
    parts_b = list(map(int, b.split('.'))

    for i in range(3):
        if parts_a[i] < parts_b[i]:
            return -1
        elif parts_a[i] > parts_b[i]:
            return 1

    return 0

