class TaskQueue:
    def __init__(self):
        self._tasks = []
        self._index = 0

    def add(self, name, priority):
        if any(task[2] == name for task in self._tasks):
            raise ValueError(f"Task '{name}' is already queued.")
        heapq.heappush(self._tasks, (priority, self._index, name))
        self._index += 1

    def pop(self):
        if not self._tasks:
            raise IndexError("Queue is empty.")
        return heapq.heappop(self._tasks)[2]

    def __len__(self):
        return len(self._tasks)

import heapq

class TaskQueue:
    def __init__(self):
        self._queue = []
        self._entry_finder = {}
        self.REMOVED = '<removed-task>'  # placeholder for a removed task
        self._counter = iter(range(1000000))  # Use an iterator for counter

    def add(self, name, priority=0):
        'Add a new task or update the priority of an existing task'
        if name in self._entry_finder:
            self.remove(name)
        count = next(self._counter)
        entry = [priority, count, name]
        self._entry_finder[name] = entry
        heapq.heappush(self._queue, entry)

    def remove(self, name):
        'Mark an existing task as REMOVED.  Raise KeyError if not found.'
        entry = self._entry_finder.pop(name)
        entry[-1] = self.REMOVED

    def pop(self):
        'Remove and return the lowest priority task. Raise KeyError if empty.'
        while self._queue:
            priority, count, name = heapq.heappop(self._queue)
            if name is not self.REMOVED:
                del self._entry_finder[name]
                return name
        raise IndexError('pop from an empty priority queue')

    def __len__(self):
        'Return the number of tasks in the queue.'
        return len(self._entry_finder)
